/// <reference lib="webworker" />

interface ParseRequest {
  id: string;
  jsonString: string;
}

interface ParseResponse {
  id: string;
  success: boolean;
  data?: any;
  error?: string;
}

addEventListener('message', ({ data }: MessageEvent<ParseRequest>) => {
  const response: ParseResponse = {
    id: data.id,
    success: false
  };

  try {
    response.data = JSON.parse(data.jsonString);
    response.success = true;
  } catch (error) {
    response.error = error instanceof Error ? error.message : 'Unknown parsing error';
  }

  postMessage(response);
});